  <style>
    /* ========================================
       CSS CUSTOM PROPERTIES
       ======================================== */
    :root {
      --color-primary: #2D6A4F;
      --color-primary-dark: #1B4332;
      --color-primary-light: #40916C;
      --color-accent: #F4A261;
      --color-accent-dark: #E76F51;
      --color-cream: #FEFAE0;
      --color-cream-dark: #F5F0D0;
      --color-white: #FFFFFF;
      --color-text: #2C2C2C;
      --color-text-light: #5A5A5A;
      --color-text-muted: #8A8A8A;
      --color-border: #E8E4D4;
      --font-heading: 'Nunito', sans-serif;
      --font-body: 'Inter', sans-serif;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.10);
      --shadow-xl: 0 16px 48px rgba(0,0,0,0.12);
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      --max-width: 1200px;
    }

    /* ========================================
       RESET & BASE
       ======================================== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

    body {
      font-family: var(--font-body);
      color: var(--color-text);
      background-color: var(--color-cream);
      line-height: 1.6;
      overflow-x: hidden;
    }

    img { max-width: 100%; height: auto; display: block; }
    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }
    input { font-family: inherit; }

    h1, h2, h3, h4, h5, h6 {
      font-family: var(--font-heading);
      line-height: 1.2;
      font-weight: 800;
    }

    .container {
      width: 100%;
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ========================================
       HEADER
       ======================================== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--color-border);
      transition: box-shadow var(--transition);
    }

    .header.scrolled {
      box-shadow: var(--shadow-md);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-heading);
      font-weight: 900;
      font-size: 1.5rem;
      color: var(--color-primary);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--color-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 1.2rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-family: var(--font-heading);
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--color-text-light);
      transition: color var(--transition);
      position: relative;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--color-primary);
      border-radius: 1px;
      transition: width var(--transition);
    }

    .nav-links a:hover { color: var(--color-primary); }
    .nav-links a:hover::after { width: 100%; }

    .mobile-menu-btn {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
    }

    .mobile-menu-btn span {
      display: block;
      width: 24px;
      height: 2.5px;
      background: var(--color-primary);
      border-radius: 2px;
      transition: var(--transition);
    }

    /* ========================================
       HERO
       ======================================== */
    .hero {
      padding: 80px 0 100px;
      background: linear-gradient(135deg, var(--color-cream) 0%, #E8F5E9 50%, var(--color-cream) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -120px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(244,162,97,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -80px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(45,106,79,0.1) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .hero-content { max-width: 560px; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(45,106,79,0.1);
      color: var(--color-primary);
      padding: 8px 16px;
      border-radius: 100px;
      font-weight: 600;
      font-size: 0.85rem;
      margin-bottom: 24px;
      font-family: var(--font-heading);
    }

    .hero h1 {
      font-size: clamp(2.5rem, 5vw, 3.5rem);
      color: var(--color-primary-dark);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: 1.15rem;
      color: var(--color-text-light);
      margin-bottom: 36px;
      max-width: 480px;
      line-height: 1.7;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius-lg);
      font-weight: 700;
      font-size: 1rem;
      font-family: var(--font-heading);
      transition: all var(--transition);
    }

    .btn-primary {
      background: var(--color-primary);
      color: white;
      box-shadow: 0 4px 16px rgba(45,106,79,0.3);
    }

    .btn-primary:hover {
      background: var(--color-primary-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 24px rgba(45,106,79,0.4);
    }

    .btn-secondary {
      background: var(--color-white);
      color: var(--color-primary);
      border: 2px solid var(--color-primary);
    }

    .btn-secondary:hover {
      background: var(--color-primary);
      color: white;
      transform: translateY(-2px);
    }

    .hero-visual {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .hero-image-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      grid-template-rows: 1fr 1fr;
      gap: 16px;
      width: 100%;
      max-width: 480px;
    }

    .hero-img-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-lg);
      aspect-ratio: 1;
      position: relative;
    }

    .hero-img-card:nth-child(1) { transform: translateY(-12px); }
    .hero-img-card:nth-child(4) { transform: translateY(12px); }

    .hero-img-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      color: white;
      font-weight: 700;
    }

    .hero-img-card:nth-child(1) .hero-img-placeholder {
      background: linear-gradient(135deg, #A8E6CF, #88D8B0);
    }
    .hero-img-card:nth-child(2) .hero-img-placeholder {
      background: linear-gradient(135deg, #FFDAB9, #F4A261);
    }
    .hero-img-card:nth-child(3) .hero-img-placeholder {
      background: linear-gradient(135deg, #FFE4B5, #F4D35E);
    }
    .hero-img-card:nth-child(4) .hero-img-placeholder {
      background: linear-gradient(135deg, #E8B4B8, #E76F51);
    }

    /* ========================================
       SECTION COMMON
       ======================================== */
    .section { padding: 80px 0; }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      color: var(--color-primary-dark);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 1.05rem;
      color: var(--color-text-light);
      max-width: 560px;
      margin: 0 auto;
    }

    /* ========================================
       FEATURED PRODUCTS CAROUSEL
       ======================================== */
    .featured-products {
      background: var(--color-white);
      padding: 80px 0;
    }

    .carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      padding: 8px 4px;
    }

    .product-card {
      flex: 0 0 calc(25% - 18px);
      min-width: 260px;
      background: var(--color-cream);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-img {
      height: 200px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      position: relative;
      overflow: hidden;
    }

    .product-card:nth-child(1) .product-img { background: linear-gradient(135deg, #FFF3E0, #FFE0B2); }
    .product-card:nth-child(2) .product-img { background: linear-gradient(135deg, #F3E5F5, #E1BEE7); }
    .product-card:nth-child(3) .product-img { background: linear-gradient(135deg, #FBE9E7, #FFCCBC); }
    .product-card:nth-child(4) .product-img { background: linear-gradient(135deg, #E8F5E9, #C8E6C9); }
    .product-card:nth-child(5) .product-img { background: linear-gradient(135deg, #FFF8E1, #FFECB3); }
    .product-card:nth-child(6) .product-img { background: linear-gradient(135deg, #FFEBEE, #FFCDD2); }
    .product-card:nth-child(7) .product-img { background: linear-gradient(135deg, #E0F7FA, #B2EBF2); }
    .product-card:nth-child(8) .product-img { background: linear-gradient(135deg, #FFF3E0, #FFE0B2); }

    .product-info {
      padding: 20px;
    }

    .product-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--color-primary-dark);
      margin-bottom: 6px;
    }

    .product-desc {
      font-size: 0.85rem;
      color: var(--color-text-muted);
      margin-bottom: 12px;
      line-height: 1.5;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .product-price {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.2rem;
      color: var(--color-primary);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--color-white);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10;
      transition: all var(--transition);
      border: 2px solid var(--color-border);
    }

    .carousel-btn:hover {
      background: var(--color-primary);
      color: white;
      border-color: var(--color-primary);
      box-shadow: var(--shadow-lg);
    }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
      stroke: currentColor;
      fill: none;
      stroke-width: 2.5;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .carousel-btn-prev { left: -8px; }
    .carousel-btn-next { right: -8px; }

    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 32px;
    }

    .carousel-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--color-border);
      transition: all var(--transition);
    }

    .carousel-dot.active {
      background: var(--color-primary);
      width: 28px;
      border-radius: 5px;
    }

    /* ========================================
       SEASONAL PICKS
       ======================================== */
    .seasonal-picks {
      background: linear-gradient(135deg, #E8F5E9 0%, var(--color-cream) 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 24px;
    }

    .seasonal-card {
      background: var(--color-white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
      position: relative;
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .seasonal-badge {
      position: absolute;
      top: 16px;
      left: 16px;
      background: var(--color-accent);
      color: white;
      padding: 4px 12px;
      border-radius: 100px;
      font-size: 0.75rem;
      font-weight: 700;
      font-family: var(--font-heading);
      z-index: 2;
    }

    .seasonal-img {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .seasonal-card:nth-child(1) .seasonal-img { background: linear-gradient(135deg, #E8F5E9, #B2DFDB); }
    .seasonal-card:nth-child(2) .seasonal-img { background: linear-gradient(135deg, #FFF3E0, #FFCC80); }
    .seasonal-card:nth-child(3) .seasonal-img { background: linear-gradient(135deg, #EFEBE9, #D7CCC8); }
    .seasonal-card:nth-child(4) .seasonal-img { background: linear-gradient(135deg, #FFF8E1, #FFE082); }

    .seasonal-info {
      padding: 20px;
    }

    .seasonal-name {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--color-primary-dark);
      margin-bottom: 6px;
    }

    .seasonal-desc {
      font-size: 0.85rem;
      color: var(--color-text-muted);
      margin-bottom: 12px;
      line-height: 1.5;
    }

    .seasonal-price {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.15rem;
      color: var(--color-primary);
    }

    /* ========================================
       CATEGORIES
       ======================================== */
    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 24px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      transition: transform var(--transition);
    }

    .category-card:nth-child(1) .category-bg { background: linear-gradient(135deg, #FFE0B2, #FFCC80); }
    .category-card:nth-child(2) .category-bg { background: linear-gradient(135deg, #C8E6C9, #A5D6A7); }
    .category-card:nth-child(3) .category-bg { background: linear-gradient(135deg, #B3E5FC, #81D4FA); }
    .category-card:nth-child(4) .category-bg { background: linear-gradient(135deg, #FFCCBC, #FF8A65); }
    .category-card:nth-child(5) .category-bg { background: linear-gradient(135deg, #FFF9C4, #FFF176); }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: rgba(27,67,50,0.65);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity var(--transition);
      padding: 20px;
      text-align: center;
    }

    .category-card:hover .category-bg { transform: scale(1.08); }
    .category-card:hover .category-overlay { opacity: 1; }

    .category-name {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.25rem;
      color: white;
      margin-bottom: 8px;
    }

    .category-subtitle {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.85);
      line-height: 1.5;
    }

    /* Permanent bottom label visible without hover */
    .category-label {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      background: linear-gradient(to top, rgba(27,67,50,0.8), transparent);
      padding: 32px 16px 16px;
      transition: opacity var(--transition);
    }

    .category-card:hover .category-label { opacity: 0; }

    .category-label-text {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1.1rem;
      color: white;
    }

    /* ========================================
       BRAND HIGHLIGHTS
       ======================================== */
    .highlights {
      background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 50%, var(--color-primary-light) 100%);
      padding: 64px 0;
      color: white;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
    }

    .highlight-item {
      padding: 16px;
    }

    .highlight-number {
      font-family: var(--font-heading);
      font-weight: 900;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1;
      margin-bottom: 8px;
      color: var(--color-accent);
    }

    .highlight-label {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 1rem;
      margin-bottom: 4px;
    }

    .highlight-desc {
      font-size: 0.85rem;
      opacity: 0.8;
      line-height: 1.5;
    }

    /* ========================================
       STORE LOCATOR
       ======================================== */
    .store-locator {
      background: var(--color-white);
    }

    .locator-box {
      max-width: 640px;
      margin: 0 auto;
    }

    .search-form {
      display: flex;
      gap: 12px;
      margin-bottom: 32px;
    }

    .search-input {
      flex: 1;
      padding: 16px 20px;
      border: 2px solid var(--color-border);
